import{_ as r,o as e,c as a,a2 as d}from"./chunks/framework.C7GIOALF.js";const p=JSON.parse('{"title":"Everyday Marvel and Spider-Man Cards","description":"","frontmatter":{},"headers":[],"relativePath":"research/everyday-life/marvel.md","filePath":"research/everyday-life/marvel.md","lastUpdated":null}'),n={name:"research/everyday-life/marvel.md"};function i(s,t,o,l,c,h){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="everyday-marvel-and-spider-man-cards" tabindex="-1">Everyday Marvel and Spider-Man Cards <a class="header-anchor" href="#everyday-marvel-and-spider-man-cards" aria-label="Permalink to &quot;Everyday Marvel and Spider-Man Cards&quot;">​</a></h1><p>Ordinary life drawn from the Marvel card pool, checked October 19, 2026. These are full individual card entries, including artifacts, Vehicles, lands, instants, sorceries, and enchantments as well as creatures.</p><p><strong>Direct</strong> means a strong ordinary-life premise; <strong>Setting</strong> means the subject is ordinary but less suited to present-day New York. Marvel&#39;s powered pets, civilian superhero identities, and other qualified exceptions appear in <a href="./almost-matches.html#marvel-and-spider-man">Almost matches</a>. See the <a href="./../everyday-life.html">catalogue guide</a> for scope and rules distinctions.</p><h2 id="people-and-jobs" tabindex="-1">People and jobs <a class="header-anchor" href="#people-and-jobs" aria-label="Permalink to &quot;People and jobs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/msc/48/alicia-masters-skilled-sculptor" target="_blank" rel="noreferrer">Alicia Masters, Skilled Sculptor</a> · MSC 48</td><td>Legendary Creature — Human Artificer</td><td>Direct</td><td>A working sculptor; an ordinary civilian gets a named role alongside the superheroes.</td></tr><tr><td><a href="https://scryfall.com/card/spm/75/angry-rabble" target="_blank" rel="noreferrer">Angry Rabble</a> · SPM 75</td><td>Creature — Human Citizen</td><td>Direct</td><td>An angry crowd of city residents. Human Citizen is the actual type line.</td></tr><tr><td><a href="https://scryfall.com/card/msc/768/aunt-may" target="_blank" rel="noreferrer">Aunt May</a> · MSC 768</td><td>Legendary Creature — Human Citizen</td><td>Direct</td><td>A family member looking after the neighborhood; the Spider bonus does not make her a Spider creature.</td></tr><tr><td><a href="https://scryfall.com/card/msh/48/bold-biochemist" target="_blank" rel="noreferrer">Bold Biochemist</a> · MSH 48</td><td>Creature — Human Scientist</td><td>Direct</td><td>A scientist at work. Research is an ordinary profession even in a superhero setting.</td></tr><tr><td><a href="https://scryfall.com/card/spm/126/cheering-crowd" target="_blank" rel="noreferrer">Cheering Crowd</a> · SPM 126</td><td>Creature — Human Citizen</td><td>Direct</td><td>Spectators become the main event; the ability involves decisions by multiple players.</td></tr><tr><td><a href="https://scryfall.com/card/msc/792/common-crook" target="_blank" rel="noreferrer">Common Crook</a> · MSC 792</td><td>Creature — Human Rogue Villain</td><td>Direct</td><td>An everyday thief, explicitly a Human Rogue Villain; Villain does not necessarily mean superpowered.</td></tr><tr><td><a href="https://scryfall.com/card/msh/14/crowd-of-true-believers" target="_blank" rel="noreferrer">Crowd of True Believers</a> · MSH 14</td><td>Creature — Human Citizen</td><td>Direct</td><td>Fans and spectators providing moral support.</td></tr><tr><td><a href="https://scryfall.com/card/msc/771/daily-bugle-reporters" target="_blank" rel="noreferrer">Daily Bugle Reporters</a> · MSC 771</td><td>Creature — Human Citizen</td><td>Direct</td><td>Working journalists, with reporting-themed modes.</td></tr><tr><td><a href="https://scryfall.com/card/spm/99/damage-control-crew" target="_blank" rel="noreferrer">Damage Control Crew</a> · SPM 99</td><td>Creature — Human Citizen</td><td>Direct</td><td>The people who have to repair and clear up the city after everyone else&#39;s adventure.</td></tr><tr><td><a href="https://scryfall.com/card/msc/784/doc-ocks-henchmen" target="_blank" rel="noreferrer">Doc Ock&#39;s Henchmen</a> · MSC 784</td><td>Creature — Human Villain</td><td>Direct</td><td>Hired muscle with a paycheck and a reluctance to fight Spider-Man.</td></tr><tr><td><a href="https://scryfall.com/card/msc/13/everett-k-ross-hapless-attach%C3%A9" target="_blank" rel="noreferrer">Everett K. Ross, Hapless Attaché</a> · MSC 13</td><td>Legendary Creature — Human Advisor</td><td>Direct</td><td>A government liaison. His commander-specific ability still needs the chosen format to make sense.</td></tr><tr><td><a href="https://scryfall.com/card/msc/772/flash-thompson-spider-fan" target="_blank" rel="noreferrer">Flash Thompson, Spider-Fan</a> · MSC 772</td><td>Legendary Creature — Human Citizen</td><td>Direct</td><td>This particular version is a civilian fan, distinct from Flash&#39;s powered identities.</td></tr><tr><td><a href="https://scryfall.com/card/msc/594/foggy-nelson-on-retainer" target="_blank" rel="noreferrer">Foggy Nelson, On Retainer</a> · MSC 594</td><td>Legendary Creature — Human Advisor</td><td>Direct</td><td>A lawyer: ideal for the legal-bills side of a city box.</td></tr><tr><td><a href="https://scryfall.com/card/msc/820/gallant-citizen" target="_blank" rel="noreferrer">Gallant Citizen</a> · MSC 820</td><td>Creature — Human Citizen</td><td>Direct</td><td>A helpful ordinary citizen, not a Hero by creature type.</td></tr><tr><td><a href="https://scryfall.com/card/spm/102/guy-in-the-chair" target="_blank" rel="noreferrer">Guy in the Chair</a> · SPM 102</td><td>Creature — Human Advisor</td><td>Direct</td><td>The friend providing technical support; the Spider-specific ability is a deck-building consideration.</td></tr><tr><td><a href="https://scryfall.com/card/msc/622/happy-hogan-bodyguard" target="_blank" rel="noreferrer">Happy Hogan, Bodyguard</a> · MSC 622</td><td>Legendary Creature — Human Advisor</td><td>Direct</td><td>A bodyguard doing his job, with no superhuman identity on this card.</td></tr><tr><td><a href="https://scryfall.com/card/msc/545/happy-hogan-dauntless-driver" target="_blank" rel="noreferrer">Happy Hogan, Dauntless Driver</a> · MSC 545</td><td>Legendary Creature — Human Pilot</td><td>Direct</td><td>A named driver; particularly appropriate for a transit or service-worker packet.</td></tr><tr><td><a href="https://scryfall.com/card/spm/81/j-jonah-jameson" target="_blank" rel="noreferrer">J. Jonah Jameson</a> · SPM 81</td><td>Legendary Creature — Human Citizen</td><td>Direct</td><td>The newspaper boss. Suspecting a pigeon is a possible game interaction, not a new house rule.</td></tr><tr><td><a href="https://scryfall.com/card/msc/34/jarvis-earths-mightiest-butler" target="_blank" rel="noreferrer">Jarvis, Earth&#39;s Mightiest Butler</a> · MSC 34</td><td>Legendary Creature — Human Advisor</td><td>Direct</td><td>A butler whose employers happen to be superheroes; his draw ability specifically needs Hero spells.</td></tr><tr><td><a href="https://scryfall.com/card/msh/102/kingpins-enforcers" target="_blank" rel="noreferrer">Kingpin&#39;s Enforcers</a> · MSH 102</td><td>Creature — Human Villain</td><td>Direct</td><td>Organized crime&#39;s collection department: ordinary people with an unpleasant job.</td></tr><tr><td><a href="https://scryfall.com/card/spm/134/mary-jane-watson" target="_blank" rel="noreferrer">Mary Jane Watson</a> · SPM 134</td><td>Legendary Creature — Human Performer</td><td>Direct</td><td>A civilian performer; the card rewards Spiders but is itself Human Performer.</td></tr><tr><td><a href="https://scryfall.com/card/spm/58/merciless-enforcers" target="_blank" rel="noreferrer">Merciless Enforcers</a> · SPM 58</td><td>Creature — Human Mercenary Villain</td><td>Direct</td><td>Street-level hired muscle, useful for ordinary-criminal themes.</td></tr><tr><td><a href="https://scryfall.com/card/msc/773/mj-rising-star" target="_blank" rel="noreferrer">MJ, Rising Star</a> · MSC 773</td><td>Legendary Creature — Human Performer</td><td>Direct</td><td>The acting career rather than a superhero identity; a separate card from Mary Jane Watson.</td></tr><tr><td><a href="https://scryfall.com/card/msc/821/mob-lookout" target="_blank" rel="noreferrer">Mob Lookout</a> · MSC 821</td><td>Creature — Human Rogue Villain</td><td>Direct</td><td>Someone watching the street while a crime takes place.</td></tr><tr><td><a href="https://scryfall.com/card/msh/26/night-nurse-healer-of-heroes" target="_blank" rel="noreferrer">Night Nurse, Healer of Heroes</a> · MSH 26</td><td>Legendary Creature — Human Doctor Hero</td><td>Direct</td><td>An ordinary medical professional treating extraordinary patients. Hero appears in the type line; that alone does not mean superpowers.</td></tr><tr><td><a href="https://scryfall.com/card/spm/40/oscorp-research-team" target="_blank" rel="noreferrer">Oscorp Research Team</a> · SPM 40</td><td>Creature — Human Scientist</td><td>Direct</td><td>Ordinary employees doing research for a spectacularly questionable company.</td></tr><tr><td><a href="https://scryfall.com/card/spm/110/professional-wrestler" target="_blank" rel="noreferrer">Professional Wrestler</a> · SPM 110</td><td>Creature — Human Warrior Performer</td><td>Direct</td><td>A sports entertainer, with Performer and Warrior types rather than Citizen.</td></tr><tr><td><a href="https://scryfall.com/card/msc/23/queen-mother-ramonda" target="_blank" rel="noreferrer">Queen Mother Ramonda</a> · MSC 23</td><td>Legendary Creature — Human Noble</td><td>Setting</td><td>An unpowered human ruler, but royalty and Wakanda are a stretch from everyday New York. Introduces the monarch rules.</td></tr><tr><td><a href="https://scryfall.com/card/msc/703/quinjet-technician" target="_blank" rel="noreferrer">Quinjet Technician</a> · MSC 703</td><td>Creature — Human Artificer</td><td>Direct</td><td>An aircraft mechanic. The specialist mana ability supports power-up cards.</td></tr><tr><td><a href="https://scryfall.com/card/msh/33/raft-security-officer" target="_blank" rel="noreferrer">Raft Security Officer</a> · MSH 33</td><td>Creature — Human Soldier</td><td>Direct</td><td>A prison guard; the job is ordinary even though the inmates and equipment are not.</td></tr><tr><td><a href="https://scryfall.com/card/msh/153/stark-industries-executive" target="_blank" rel="noreferrer">Stark Industries Executive</a> · MSH 153</td><td>Creature — Human Advisor</td><td>Direct</td><td>Corporate administration and financing, rather than a suit of superhero armor.</td></tr><tr><td><a href="https://scryfall.com/card/spm/119/supportive-parents" target="_blank" rel="noreferrer">Supportive Parents</a> · SPM 119</td><td>Creature — Human Citizen</td><td>Direct</td><td>Parents helping their child: one of the clearest everyday-life cards.</td></tr><tr><td><a href="https://scryfall.com/card/msc/811/taxi-driver" target="_blank" rel="noreferrer">Taxi Driver</a> · MSC 811</td><td>Creature — Human Pilot</td><td>Direct</td><td>Exactly the urban transport worker the theme wants.</td></tr><tr><td><a href="https://scryfall.com/card/spe/15/the-mary-janes" target="_blank" rel="noreferrer">The Mary Janes</a> · SPE 15</td><td>Legendary Creature — Human Bard Performer</td><td>Direct</td><td>A band. The members&#39; other stories do not change this card&#39;s musical premise.</td></tr><tr><td><a href="https://scryfall.com/card/msc/812/unlucky-witness" target="_blank" rel="noreferrer">Unlucky Witness</a> · MSC 812</td><td>Creature — Human Citizen</td><td>Direct</td><td>Someone who saw the wrong thing at the wrong time.</td></tr><tr><td><a href="https://scryfall.com/card/msc/101/willie-lumpkin-postman" target="_blank" rel="noreferrer">Willie Lumpkin, Postman</a> · MSC 101</td><td>Legendary Creature — Human Citizen</td><td>Direct</td><td>Postal delivery continues even when the city is full of superheroes.</td></tr></tbody></table><h2 id="animals" tabindex="-1">Animals <a class="header-anchor" href="#animals" aria-label="Permalink to &quot;Animals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/msc/170/birds-of-paradise" target="_blank" rel="noreferrer">Birds of Paradise</a> · MSC 170</td><td>Creature — Bird</td><td>Setting</td><td>Ordinary birds in a Marvel printing; wildlife rather than a pigeon on the subway. Inspect the particular art rather than inferring the species from the card name.</td></tr><tr><td><a href="https://scryfall.com/card/msc/769/city-pigeon" target="_blank" rel="noreferrer">City Pigeon</a> · MSC 769</td><td>Creature — Bird</td><td>Direct</td><td>The central city-wildlife joke. Bird, not Citizen; its departure creates a Food token.</td></tr><tr><td><a href="https://scryfall.com/card/spm/104/kravens-cats" target="_blank" rel="noreferrer">Kraven&#39;s Cats</a> · SPM 104</td><td>Creature — Cat Villain</td><td>Setting</td><td>Trained big cats associated with a villain. More zoo or escaped-animal material than normal street pets.</td></tr><tr><td><a href="https://scryfall.com/card/msc/726/lucky-the-pizza-dog" target="_blank" rel="noreferrer">Lucky the Pizza Dog</a> · MSC 726</td><td>Legendary Creature — Dog</td><td>Direct</td><td>An ordinary named dog with an extremely suitable interest in food.</td></tr><tr><td><a href="https://scryfall.com/card/msc/748/wakandan-tusker" target="_blank" rel="noreferrer">Wakandan Tusker</a> · MSC 748</td><td>Creature — Elephant</td><td>Setting</td><td>An elephant rather than a superhero; better as zoo or wildlife material than a New York native.</td></tr></tbody></table><h2 id="objects-and-transportation" tabindex="-1">Objects and transportation <a class="header-anchor" href="#objects-and-transportation" aria-label="Permalink to &quot;Objects and transportation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/spm/161/bagel-and-schmear" target="_blank" rel="noreferrer">Bagel and Schmear</a> · SPM 161</td><td>Artifact — Food</td><td>Direct</td><td>Breakfast as a game piece; an actual Food artifact with two ways to use it.</td></tr><tr><td><a href="https://scryfall.com/card/msc/749/daily-bugle-newspaper" target="_blank" rel="noreferrer">Daily Bugle Newspaper</a> · MSC 749</td><td>Artifact</td><td>Direct</td><td>A physical newspaper, distinct from the building and the reporters.</td></tr><tr><td><a href="https://scryfall.com/card/spm/164/hot-dog-cart" target="_blank" rel="noreferrer">Hot Dog Cart</a> · SPM 164</td><td>Artifact</td><td>Direct</td><td>Street food and a mana source in one ordinary piece of city equipment.</td></tr><tr><td><a href="https://scryfall.com/card/spm/169/news-helicopter" target="_blank" rel="noreferrer">News Helicopter</a> · SPM 169</td><td>Artifact Creature — Construct</td><td>Direct</td><td>Local news transport. It is an artifact creature — Construct, not a Vehicle, and it creates a Citizen token.</td></tr><tr><td><a href="https://scryfall.com/card/spm/170/passenger-ferry" target="_blank" rel="noreferrer">Passenger Ferry</a> · SPM 170</td><td>Artifact — Vehicle</td><td>Direct</td><td>Ordinary public transportation; an actual Vehicle with crew 2.</td></tr><tr><td><a href="https://scryfall.com/card/spm/171/peter-parkers-camera" target="_blank" rel="noreferrer">Peter Parker&#39;s Camera</a> · SPM 171</td><td>Artifact</td><td>Direct</td><td>Ordinary photography equipment with film counters, despite its famous owner&#39;s name.</td></tr><tr><td><a href="https://scryfall.com/card/spm/109/pictures-of-spider-man" target="_blank" rel="noreferrer">Pictures of Spider-Man</a> · SPM 109</td><td>Artifact</td><td>Direct</td><td>Selling photographs to a newspaper is mundane even when the subject is a superhero.</td></tr><tr><td><a href="https://scryfall.com/card/spm/177/steel-wrecking-ball" target="_blank" rel="noreferrer">Steel Wrecking Ball</a> · SPM 177</td><td>Artifact</td><td>Direct</td><td>A real demolition tool; the surrounding superhero action does not change the object&#39;s ordinary nature.</td></tr><tr><td><a href="https://scryfall.com/card/spm/178/subway-train" target="_blank" rel="noreferrer">Subway Train</a> · SPM 178</td><td>Artifact — Vehicle</td><td>Direct</td><td>The commute becomes a win condition. Vehicle with crew 2, not a creature card in the library.</td></tr><tr><td><a href="https://scryfall.com/card/mar/7/wedding-ring" target="_blank" rel="noreferrer">Wedding Ring</a> · MAR 7</td><td>Artifact</td><td>Direct</td><td>An everyday ceremonial object. Its gameplay involves copying the ring and linking players, so check the format.</td></tr></tbody></table><h2 id="places" tabindex="-1">Places <a class="header-anchor" href="#places" aria-label="Permalink to &quot;Places&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/spm/179/daily-bugle-building" target="_blank" rel="noreferrer">Daily Bugle Building</a> · SPM 179</td><td>Land</td><td>Direct</td><td>A newspaper office in the city; pairs naturally with its staff and paper.</td></tr><tr><td><a href="https://scryfall.com/card/msc/754/fogwells-gym" target="_blank" rel="noreferrer">Fogwell&#39;s Gym</a> · MSC 754</td><td>Land</td><td>Direct</td><td>An ordinary boxing gym with an especially good street-level identity.</td></tr><tr><td><a href="https://scryfall.com/card/msh/268/hells-kitchen" target="_blank" rel="noreferrer">Hell&#39;s Kitchen</a> · MSH 268</td><td>Land</td><td>Direct</td><td>A real New York neighborhood, represented as a land.</td></tr><tr><td><a href="https://scryfall.com/card/spm/185/suburban-sanctuary" target="_blank" rel="noreferrer">Suburban Sanctuary</a> · SPM 185</td><td>Land</td><td>Direct</td><td>A family home. More neighborhood/suburban than downtown, but clearly ordinary life.</td></tr><tr><td><a href="https://scryfall.com/card/spm/186/university-campus" target="_blank" rel="noreferrer">University Campus</a> · SPM 186</td><td>Land</td><td>Direct</td><td>Higher education and homework, with a city-appropriate setting.</td></tr><tr><td><a href="https://scryfall.com/card/spm/187/urban-retreat" target="_blank" rel="noreferrer">Urban Retreat</a> · SPM 187</td><td>Land</td><td>Direct</td><td>Apartment hunting and somewhere to live; an excellent companion to Rent Is Due.</td></tr><tr><td><a href="https://scryfall.com/card/spm/188/vibrant-cityscape" target="_blank" rel="noreferrer">Vibrant Cityscape</a> · SPM 188</td><td>Land</td><td>Direct</td><td>The city itself, without requiring a named superhero headquarters.</td></tr></tbody></table><h2 id="everyday-activities" tabindex="-1">Everyday activities <a class="header-anchor" href="#everyday-activities" aria-label="Permalink to &quot;Everyday activities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Card and printing</th><th>Actual type</th><th>Fit</th><th>Why consider it / qualification</th></tr></thead><tbody><tr><td><a href="https://scryfall.com/card/msh/162/call-damage-control" target="_blank" rel="noreferrer">Call Damage Control</a> · MSH 162</td><td>Sorcery</td><td>Direct</td><td>Calling the repair crew after something has gone wrong.</td></tr><tr><td><a href="https://scryfall.com/card/spm/8/friendly-neighborhood" target="_blank" rel="noreferrer">Friendly Neighborhood</a> · SPM 8</td><td>Enchantment — Aura</td><td>Direct</td><td>An Aura that supplies ordinary Citizen tokens and a community-support ability.</td></tr><tr><td><a href="https://scryfall.com/card/spm/60/parker-luck" target="_blank" rel="noreferrer">Parker Luck</a> · SPM 60</td><td>Enchantment</td><td>Direct</td><td>Bad luck and life refusing to go to plan. The particular unlucky resident happens to be Peter Parker.</td></tr><tr><td><a href="https://scryfall.com/card/msh/31/political-triumph" target="_blank" rel="noreferrer">Political Triumph</a> · MSH 31</td><td>Enchantment — Plan</td><td>Direct</td><td>Politics as a city-life theme. It is an Enchantment — Plan, not an instant or sorcery.</td></tr><tr><td><a href="https://scryfall.com/card/spm/11/rent-is-due" target="_blank" rel="noreferrer">Rent Is Due</a> · SPM 11</td><td>Enchantment</td><td>Direct</td><td>An enchantment about paying rent: one of the strongest everyday New York jokes.</td></tr><tr><td><a href="https://scryfall.com/card/msc/808/romantic-rendezvous" target="_blank" rel="noreferrer">Romantic Rendezvous</a> · MSC 808</td><td>Sorcery</td><td>Direct</td><td>Going on a date; no need to remove the card&#39;s normal draw/discard effect.</td></tr><tr><td><a href="https://scryfall.com/card/spm/42/school-daze" target="_blank" rel="noreferrer">School Daze</a> · SPM 42</td><td>Instant</td><td>Direct</td><td>Exact spelling is Daze. An instant with Do Homework and Fight Crime modes; the homework premise qualifies, and both modes remain legal.</td></tr><tr><td><a href="https://scryfall.com/card/msc/817/scout-the-city" target="_blank" rel="noreferrer">Scout the City</a> · MSC 817</td><td>Sorcery</td><td>Direct</td><td>Looking around town; its alternate removal mode does not erase that ordinary premise.</td></tr><tr><td><a href="https://scryfall.com/card/msc/813/wisecrack" target="_blank" rel="noreferrer">Wisecrack</a> · MSC 813</td><td>Instant</td><td>Direct</td><td>Making a joke at someone&#39;s expense. Superhero context, ordinary human behavior.</td></tr></tbody></table>',13)])])}const f=r(n,[["render",i]]);export{p as __pageData,f as default};
